let landingPageCurrentReviewPosition = 1;

const showCurrentReview = (numReviews) => {
  const landingReviewsContainer = document.getElementById('landing-reviews-reviews');

  const currentReview = landingReviewsContainer.children[landingPageCurrentReviewPosition]

  const reviews = currentReview.parentElement;
  const currentReviewLeft = currentReview.offsetLeft;
  const currentReviewWidth = currentReview.offsetWidth;
  const reviewsWidth = reviews.clientWidth;

  reviews.scrollLeft = currentReviewLeft - (reviewsWidth / 2) + (currentReviewWidth / 2) -  20;
};

const showPreviousReview = (numReviews) => {
  const landingReviewsContainer = document.getElementById('landing-reviews-reviews');

  if (landingPageCurrentReviewPosition > 1) {
    landingPageCurrentReviewPosition--;
  } else {
    landingPageCurrentReviewPosition = 3;
  }

  landingReviewsContainer.children[landingPageCurrentReviewPosition].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' })
};

const showNextReview = (numReviews) => {
  const landingReviewsContainer = document.getElementById('landing-reviews-reviews');

  if (landingPageCurrentReviewPosition < 3) {
    landingPageCurrentReviewPosition++;
  }  else {
    landingPageCurrentReviewPosition = 1;
  }

  landingReviewsContainer.children[landingPageCurrentReviewPosition].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' })
}

window.addEventListener('DOMContentLoaded', () => {
  const landingReviewsContainer = document.getElementById('landing-reviews-reviews');
  const landingReviewsPreviousButton = document.getElementById('landing-reviews-reviews-controls-button-prev');
  const landingReviewsNextButton = document.getElementById('landing-reviews-reviews-controls-button-next');

  let numReviews = 3;

  landingReviewsPreviousButton.addEventListener('click', () => showPreviousReview(numReviews));
  landingReviewsNextButton.addEventListener('click', () => showNextReview(numReviews));

  if (window.innerWidth < 768) {
    showCurrentReview();
  }

  window.addEventListener('resize', () => {
    if (window.innerWidth < 768) {
      showCurrentReview();
    }
  })
});

window.addEventListener('DOMContentLoaded', () => {
  const scrollLeftButton = document.getElementById('landing-featured-section-scroll-left');
  const scrollRightButton = document.getElementById('landing-featured-section-scroll-right');
  const featuredReviewsList = document.getElementById('landing-featured-section-list');
  const featuredReviews = featuredReviewsList.querySelectorAll('li');
  let currentIndex = 0;

  scrollLeftButton.addEventListener('click', () => {
    if (currentIndex > 0) {
      currentIndex--;
    } else {
      currentIndex = 3;
    }
    featuredReviews[currentIndex].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' })
  })

  scrollRightButton.addEventListener('click', () => {
    if (currentIndex < 3) {
      currentIndex++;
    } else {
      currentIndex = 0;
    }

    featuredReviews[currentIndex].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' })
  })
})

window.addEventListener('DOMContentLoaded', () => {
  const landingFAQSectionQuestionHeaders = document.querySelectorAll('.landing-faq-section-question-header');

  landingFAQSectionQuestionHeaders.forEach((header) => {
    header.addEventListener('click', () => {
      const question = header.parentElement;
      const answer = question.querySelector('.landing-faq-section-question-answer');

      if (answer.style.gridTemplateRows == '1fr') {
        answer.style.gridTemplateRows = '0fr';
        header.querySelector('svg').style.transform = 'rotate(0deg)';
        question.classList.remove('landing-faq-section-question-active')
      } else {
        landingFAQSectionQuestionHeaders.forEach((h) => {
          const hAnswer = h.parentElement.querySelector('.landing-faq-section-question-answer');

          h.parentElement.classList.remove('landing-faq-section-question-active')
          hAnswer.style.gridTemplateRows = '0fr';
          h.querySelector('svg').style.transform = 'rotate(0deg)';
        })

        answer.style.gridTemplateRows = '1fr';
        question.classList.add('landing-faq-section-question-active')
        header.querySelector('svg').style.transform = 'rotate(180deg)';
      }
    });
  });
});

const showLandingPagePopupContainer = () => {
  const landingPagePopupContainer = document.getElementById('landing-page-change-plan-popup-container');
  landingPagePopupContainer.style.display = 'flex';
}

const hideLandingPagePopupContainer = () => {
  const landingPagePopupContainer = document.getElementById('landing-page-change-plan-popup-container');
  landingPagePopupContainer.style.display = 'none';
}

window.addEventListener('DOMContentLoaded', () => {
  const landingPagePopupContainer = document.getElementById('landing-page-change-plan-popup-container');

  landingPagePopupContainer.addEventListener('click', hideLandingPagePopupContainer)
});

const openLandingPagePopupMain = (plan) => {
  const landingPagePopupMain = document.getElementById('landing-page-change-plan-popup-main');
  const selectionDisplay = document.getElementById('landing-page-change-plan-popup-selected');
  const planDisplay = document.getElementById('landing-page-change-plan-popup-plan');
  const changeSelectionButton = document.getElementById('landing-page-change-plan-popup-change-selection-button');

  const switchPlan = () => {
    switch(plan) {
      case 'Rural Home':
        showRuralHome();
        break;
      case 'RV and Travel':
        showRVRecreational();
        break;
      case 'Trucking':
        showTrucking();
        break;
      case 'Work and Travel':
        showHomeRoad();
        break;
      case 'Mobile Professionals':
        showMobileProfessionals();
        break;
      default:
        break;
    }

    window.currentPlan = plan;
    closeLandingPagePopupMain();
    hideLandingPagePopupContainer();
  }

  changeSelectionButton.addEventListener('click', switchPlan);

  if (window.currentPlan && window.currentPlan != plan) {
    selectionDisplay.innerHTML = window.currentPlan;
    planDisplay.innerHTML = plan;
    landingPagePopupMain.style.display = 'flex';
    return true;
  } else {
    switchPlan();
    return false;
  }
}

const closeLandingPagePopupMain = () => {
  const landingPagePopupMain = document.getElementById('landing-page-change-plan-popup-main');
  landingPagePopupMain.style.display = 'none';

}

window.addEventListener('DOMContentLoaded', () => {
  const landingPagePopupMain = document.getElementById('landing-page-change-plan-popup-main');
  const landingPagePopupMainCloseButton = document.getElementById('landing-page-change-plan-popup-main-close-button');
  const landingPagePopupMainTriggers = document.querySelectorAll('.landing-page-change-plan-popup-trigger');
  const landingPagePopupMainCloseTriggers = document.querySelectorAll('.landing-page-change-plan-popup-close-trigger');

  landingPagePopupMainCloseButton.addEventListener('click', hideLandingPagePopupContainer)
  landingPagePopupMain.addEventListener('click', (e) => e.stopPropagation());

  landingPagePopupMainTriggers.forEach((trigger) => {
    trigger.addEventListener('click', (e) => {
      const plan = e.currentTarget.dataset.plan;
      if (openLandingPagePopupMain(plan)) showLandingPagePopupContainer();
    });
  });

  landingPagePopupMainCloseTriggers.forEach((trigger) => {
    trigger.addEventListener('click', (e) => {
      hideLandingPagePopupContainer();
    });
  });
});
